    const opts = [T(`d=${dfrac('|(\\vec q-\\vec p)\\cdot\\vec n|', '|\\vec n|')}`, true), T('d=|\\vec q-\\vec p|', false, 'Das ist der Abstand der Stützpunkte. Der kürzeste Abstand ist meist kleiner.'), T(`d=${dfrac('|\\vec u\\cdot\\vec v|', '|\\vec n|')}`, false, 'Die Richtungsvektoren allein sagen nichts über den Abstand – die Stützpunkte fehlen.'), T('d=|(\\vec q-\\vec p)\\times\\vec n|', false, 'Verwendet wird das Skalarprodukt mit dem Normalenvektor: der Anteil in Richtung der gemeinsamen Senkrechten.')];
