export const GENS8 = { genUmkehr, genWurzelAbl, genIntegralfunktion, genNewton, genOrtskurve, genHesse, genSchnittgerade, genWindschief, genSpiegelung, genBewegung, genZweiseitig, genHistogramm, genRueckwaerts, genStetig, genMengen, genBinomVerteilung };
for (const [fn, topic] of [[genUmkehr, 'Umkehrfunktion'], [genWurzelAbl, 'Wurzelfunktion ableiten'], [genIntegralfunktion, 'Integralfunktion'], [genNewton, 'Newton-Verfahren'], [genOrtskurve, 'Ortskurven'], [genHesse, 'Hesse-Form'], [genSchnittgerade, 'Schnittgerade'],
  [genWindschief, 'Windschiefe Geraden'], [genSpiegelung, 'Spiegelungen'], [genBewegung, 'Bewegungen'], [genZweiseitig, 'Zweiseitiger Test'], [genHistogramm, 'Histogramme'], [genRueckwaerts, 'Rückwärts fragen'], [genStetig, 'Stetige Zufallsgrößen'], [genMengen, 'Mengenschreibweise'], [genBinomVerteilung, 'Binomialverteilung: einzeln und kumuliert']]) fn.topic = topic;
